"use client";

import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import { CreditCard, Loader2, ShieldAlert } from "lucide-react";
import { toast } from "sonner";
import { clsx } from "clsx";
import type { ActionResult } from "@/lib/errors";
import { Button } from "@/components/ui/button";

type Result = ActionResult<{ id: string; status: string }>;

/**
 * Simulated payment step. The idempotency key is generated by the server when the checkout
 * page renders, so double-clicks and retries cannot create duplicate bookings or orders.
 */
export function PayForm({ total, idempotencyKey, pay, successPath, failurePath }: { total: string; idempotencyKey: string; pay: (input: unknown) => Promise<Result>; successPath: string; failurePath: string }) {
  const router = useRouter();
  const [outcome, setOutcome] = useState<"approve" | "decline">("approve");
  const [pending, start] = useTransition();
  return (
    <div>
      <div className="flex items-start gap-3 rounded-xl border border-amber/30 bg-amber-50 p-4 text-sm text-amber">
        <ShieldAlert className="mt-0.5 size-5 shrink-0" />
        <p><strong>DEMO PAYMENT — No real money will be charged.</strong> Choose the outcome you want to simulate.</p>
      </div>
      <fieldset className="mt-4 grid grid-cols-1 gap-2 sm:grid-cols-2">
        <legend className="label">Simulated card result</legend>
        {(["approve", "decline"] as const).map((o) => (
          <label key={o} className={clsx("flex cursor-pointer items-center gap-3 rounded-xl border p-4 text-sm", outcome === o ? "border-forest bg-forest-50" : "border-line bg-white")}>
            <input type="radio" name="outcome" value={o} checked={outcome === o} onChange={() => setOutcome(o)} className="accent-forest" data-testid={`outcome-${o}`} />
            <span>
              <span className="block font-semibold">{o === "approve" ? "Approve payment" : "Decline payment"}</span>
              <span className="text-ink-soft">{o === "approve" ? "Demo card ending 4242" : "Simulates a bank decline"}</span>
            </span>
          </label>
        ))}
      </fieldset>
      <Button
        size="lg"
        className="mt-5 w-full"
        disabled={pending}
        data-testid="pay-button"
        onClick={() =>
          start(async () => {
            const r = await pay({ idempotencyKey, outcome });
            if (!r.ok) return void toast.error(r.error);
            const failed = r.data.status === "PAYMENT_FAILED";
            if (failed) toast.error("The demo payment was declined. Nothing was charged.");
            else toast.success("Demo payment successful");
            router.push((failed ? failurePath : successPath).replace(":id", r.data.id));
          })
        }
      >
        {pending ? <Loader2 className="size-4 animate-spin" /> : <CreditCard className="size-4" />}
        Pay {total} (demo)
      </Button>
    </div>
  );
}
